/* CLN4U — Unit 3: Human Rights — levels 1–4 */
window.QBANK = window.QBANK || [];
window.QBANK.push(
/* ---------- Lesson 1: What Are Human Rights? ---------- */
{u:3,l:1,t:"Vocabulary",d:1,q:"What are human rights?",a:"Entitlements every person holds simply by virtue of being human, not granted by a government",x:["Privileges a government can create or revoke","Benefits earned through good citizenship","Rights that apply only to citizens"]},
{u:3,l:1,t:"Vocabulary",d:1,q:"Which word means human rights 'apply to everyone, everywhere'?",a:"Universal",x:["Inalienable","Indivisible","Relative"]},
{u:3,l:1,t:"Vocabulary",d:1,q:"Which word means human rights 'cannot be given up or taken away'?",a:"Inalienable",x:["Universal","Indivisible","Situated"]},
{u:3,l:1,t:"Vocabulary",d:1,q:"Which word means all categories of rights are equally important?",a:"Indivisible",x:["Universal","Inalienable","Codified"]},
{u:3,l:1,t:"Theories & Concepts",d:1,q:"Which category of rights protects the individual from the state, such as freedom of expression and a fair trial?",a:"Civil and political rights",x:["Economic, social, and cultural rights","Mobility rights","Language rights"]},
{u:3,l:1,t:"Theories & Concepts",d:1,q:"Which category of rights includes education, health care, and an adequate standard of living?",a:"Economic, social, and cultural rights",x:["Civil and political rights","Legal rights","Democratic rights"]},
{u:3,l:1,t:"Laws & Documents",d:1,q:"What ancient Persian artifact from c. 539 BCE is sometimes called an early declaration of rights?",a:"The Cyrus Cylinder",x:["The Magna Carta","The Code of Hammurabi","The Rosetta Stone"]},
{u:3,l:1,t:"Laws & Documents",d:1,q:"In what year was the Universal Declaration of Human Rights adopted?",a:"1948",x:["1945","1982","1215"]},
{u:3,l:1,t:"People & Institutions",d:1,q:"In what year was the United Nations founded?",a:"1945",x:["1948","1919","1960"]},
{u:3,l:1,t:"Laws & Documents",d:1,q:"Which 1789 French document described rights as universal entitlements of citizens?",a:"The Declaration of the Rights of Man and of the Citizen",x:["The Napoleonic Code","The Magna Carta","The Social Contract"]},
{u:3,l:1,t:"Laws & Documents",d:1,q:"In what year was the American Declaration of Independence issued?",a:"1776",x:["1789","1689","1812"]},
{u:3,l:1,t:"Theories & Concepts",d:2,q:"How do human rights differ from a privilege or legal benefit?",a:"A government can create, limit, or take away a privilege; human rights exist regardless",x:["Privileges are universal; rights are not","Rights must be earned; privileges are automatic","There is no difference"]},
{u:3,l:1,t:"Theories & Concepts",d:2,q:"What claim does human rights theory add to the Unit 1 social contract?",a:"Some rights exist whether or not any government recognizes them at all",x:["Government creates all rights","Rights come only from the Charter","Only citizens have rights"]},
{u:3,l:1,t:"Theories & Concepts",d:2,q:"During the 20th century, which category of rights did Western nations emphasize, and which did the Soviet bloc emphasize?",a:"The West emphasized civil and political rights; the Soviet bloc emphasized economic, social, and cultural rights",x:["Both emphasized only civil rights","The West emphasized economic rights; the Soviets civil rights","Neither recognized any rights"]},
{u:3,l:1,t:"Laws & Documents",d:2,q:"What did the Cyrus Cylinder describe?",a:"Freeing enslaved people and allowing religious freedom after Cyrus the Great's conquest of Babylon",x:["The creation of the first parliament","A ban on torture","The first trial by jury"]},
{u:3,l:1,t:"Theories & Concepts",d:2,q:"Which traditions independently developed ideas of duty, dignity, and justice before the term 'human rights' existed?",a:"Confucian, Islamic, Hindu, and Indigenous legal traditions, among others",x:["Only Western European traditions","Only the Roman Empire","Only the United Nations"]},
{u:3,l:1,t:"Laws & Documents",d:2,q:"Why were the American and French declarations significant in the history of rights?",a:"They were the first documents to describe rights as universal entitlements of citizens, not privileges granted by a monarch",x:["They were the first written laws ever","They created the United Nations","They abolished slavery worldwide"]},
{u:3,l:1,t:"Theories & Concepts",d:2,q:"How did early rights documents fall short in practice?",a:"The French Declaration excluded women and enslaved people, and 'all men are created equal' coexisted with slavery",x:["They applied to everyone immediately","They were never published","They were written in secret"]},
{u:3,l:1,t:"Theories & Concepts",d:2,q:"Which movements expanded who rights applied to in the 19th and 20th centuries?",a:"Abolition of slavery, women's suffrage, labour rights, and decolonization",x:["The Crusades and Reformation","The Industrial Revolution only","The founding of NATO"]},
{u:3,l:1,t:"Theories & Concepts",d:2,q:"What was the 'post-war turning point' for human rights?",a:"WWII and the Holocaust convinced the world that rights could not be left to individual governments, leading to the UN and the UDHR",x:["The end of the Cold War","The invention of the printing press","The signing of the Magna Carta"]},
{u:3,l:1,t:"Theories & Concepts",d:2,q:"What became 'a matter of legitimate international concern' after 1948?",a:"How a government treated its own citizens",x:["Trade tariffs between nations","Olympic medal counts","Religious doctrine"]},
{u:3,l:1,t:"Theories & Concepts",d:2,q:"What pattern does the course say recurs across the UDHR and the Charter?",a:"A right being declared in principle long before it is extended in practice",x:["Rights being removed as soon as they are declared","Rights applying only to monarchs","Rights requiring a jury trial"]},
{u:3,l:1,t:"Theories & Concepts",d:3,q:"A government says it will 'grant' citizens the right to free speech as a reward for loyalty. Why does this misunderstand human rights?",a:"Human rights are held by virtue of being human; they are not earned or granted as a favour",x:["Free speech is not a human right","Only courts can grant rights","Loyalty is required for all rights"]},
{u:3,l:1,t:"Theories & Concepts",d:3,q:"A country protects elections and free speech but provides no access to education or health care. Which category of rights is it neglecting?",a:"Economic, social, and cultural rights",x:["Civil and political rights","Democratic rights","Mobility rights"]},
{u:3,l:1,t:"Theories & Concepts",d:3,q:"A state provides housing and health care but jails critics of the government. Which category of rights is being violated?",a:"Civil and political rights",x:["Economic, social, and cultural rights","Language rights","Property rights"]},
{u:3,l:1,t:"Laws & Documents",d:3,q:"A constitution declares equality for all, but a minority is still barred from voting in practice. Which Lesson 1 pattern does this match?",a:"A right declared in principle but not yet realized in practice",x:["Rights being indivisible","The social contract","Universal jurisdiction"]},
{u:3,l:1,t:"Theories & Concepts",d:3,q:"A person argues that because a right cannot be taken away even by consent, it is…",a:"Inalienable",x:["Divisible","Discretionary","Codified"]},
{u:3,l:1,t:"Theories & Concepts",d:3,q:"A philosopher argues that standards of justice exist independently of any government's laws. Which tradition from Unit 1 is this?",a:"Natural law",x:["Legal positivism","Critical legal theory","Legal realism"]},
{u:3,l:1,t:"Theories & Concepts",d:4,q:"Can you have full civil and political rights without economic and social rights? What does 'indivisibility' suggest?",a:"Indivisibility says all categories are equally important and depend on each other — e.g. voting matters little without education",x:["Civil rights are all that matter","Economic rights make civil rights unnecessary","The categories never overlap"]},
{u:3,l:1,t:"Laws & Documents",d:4,q:"How does the Magna Carta (Unit 1) fit into the history of human rights?",a:"It was an early seed of the idea that authority has limits, though it was not a universal rights document",x:["It was the first universal declaration of rights","It created the United Nations","It abolished monarchy"]},
{u:3,l:1,t:"Laws & Documents",d:4,q:"Why does the course emphasize that non-Western traditions developed ideas of dignity and justice independently?",a:"It anticipates the 'westernization critique' of the UDHR by showing rights ideas are not uniquely Western",x:["To prove only Western ideas matter","To show the UDHR copied Confucius","To argue that rights are relative"]},
{u:3,l:1,t:"People & Institutions",d:4,q:"How do the Enlightenment thinkers of Unit 1 connect to Lesson 1's history of rights?",a:"Hobbes, Locke, and Rousseau developed the idea of natural, inherent rights that shaped the American and French declarations",x:["They wrote the UDHR","They opposed all rights","They founded the United Nations"]},

/* ---------- Lesson 2: The Charter, Section by Section (Part 1) ---------- */
{u:3,l:2,t:"Laws & Documents",d:1,q:"Section 1 of the Charter is sometimes called what?",a:"The limitation clause (reasonable limits clause)",x:["The notwithstanding clause","The equality clause","The supremacy clause"]},
{u:3,l:2,t:"Laws & Documents",d:1,q:"Which Charter section protects mobility rights?",a:"Section 6",x:["Section 3","Section 8","Section 15"]},
{u:3,l:2,t:"Laws & Documents",d:1,q:"Which Charter section guarantees freedom from unreasonable search or seizure?",a:"Section 8",x:["Section 7","Section 9","Section 12"]},
{u:3,l:2,t:"Laws & Documents",d:1,q:"Which Charter section guarantees freedom from cruel and unusual punishment?",a:"Section 12",x:["Section 7","Section 10","Section 14"]},
{u:3,l:2,t:"Laws & Documents",d:1,q:"Which Charter section guarantees the right to an interpreter?",a:"Section 14",x:["Section 13","Section 11","Section 23"]},
{u:3,l:2,t:"Laws & Documents",d:1,q:"Which Charter section protects against self-incrimination?",a:"Section 13",x:["Section 11","Section 14","Section 9"]},
{u:3,l:2,t:"Laws & Documents",d:1,q:"Which Charter section includes the right to be informed of reasons for arrest and to retain counsel?",a:"Section 10",x:["Section 8","Section 11","Section 7"]},
{u:3,l:2,t:"Laws & Documents",d:1,q:"Which Charter section sets a maximum five-year term for the House of Commons?",a:"Section 4",x:["Section 3","Section 5","Section 33"]},
{u:3,l:2,t:"Laws & Documents",d:1,q:"Which Charter section requires Parliament and legislatures to sit at least once every twelve months?",a:"Section 5",x:["Section 4","Section 3","Section 6"]},
{u:3,l:2,t:"Cases & Rulings",d:1,q:"Which 1985 case struck down a federal Sunday closing law under freedom of religion?",a:"R. v. Big M Drug Mart Ltd.",x:["Hunter v. Southam","R. v. Jordan","R. v. Oakes"]},
{u:3,l:2,t:"Cases & Rulings",d:1,q:"Which 1984 case set the standard for a 'reasonable' search under section 8?",a:"Hunter v. Southam",x:["R. v. Big M Drug Mart","R. v. Jordan","Andrews v. Law Society"]},
{u:3,l:2,t:"Cases & Rulings",d:1,q:"Which 2016 case set strict time limits for 'trial within a reasonable time'?",a:"R. v. Jordan",x:["Hunter v. Southam","R. v. Oakes","R. v. Big M Drug Mart"]},
{u:3,l:2,t:"Laws & Documents",d:1,q:"Which Charter subsection guarantees the right to a jury trial?",a:"Section 11(f)",x:["Section 11(b)","Section 11(d)","Section 2(b)"]},
{u:3,l:2,t:"Laws & Documents",d:2,q:"What does section 1 of the Charter say?",a:"Rights are guaranteed 'subject only to such reasonable limits prescribed by law as can be demonstrably justified in a free and democratic society'",x:["Rights can never be limited","Rights apply only to citizens","Parliament may override any right for five years"]},
{u:3,l:2,t:"Laws & Documents",d:2,q:"Why does section 1 exist?",a:"No right is absolute — government needs some ability to limit rights for legitimate reasons, within strict limits",x:["To let police ignore the Charter","To give judges unlimited power","To exempt the provinces"]},
{u:3,l:2,t:"Laws & Documents",d:2,q:"What two questions does every Charter case eventually ask?",a:"Was a right violated, and if so, can section 1 save the violation?",x:["Is the accused guilty, and what is the sentence?","Is the law federal, and is it provincial?","Was the bill read three times, and did it get Royal Assent?"]},
{u:3,l:2,t:"Laws & Documents",d:2,q:"What four freedoms does section 2 protect?",a:"Conscience and religion; thought, belief, opinion and expression (including the press); peaceful assembly; and association",x:["Vote, run for office, hold elections, and sit yearly","Life, liberty, security, and property","Enter, remain, leave, and work"]},
{u:3,l:2,t:"Laws & Documents",d:2,q:"Why do the fundamental freedoms exist, according to the course?",a:"Without them, citizens cannot organize, worship, speak, or criticize government — a democracy needs them to function",x:["To protect property values","To guarantee employment","To limit the courts"]},
{u:3,l:2,t:"Laws & Documents",d:2,q:"What do sections 3–5 guarantee about elections?",a:"That elections actually happen regularly and that citizens can both vote and be voted for",x:["That all citizens must vote","That the Senate is elected","That elections are held every year"]},
{u:3,l:2,t:"Laws & Documents",d:2,q:"What do mobility rights under section 6 protect?",a:"The right to enter, remain in, and leave Canada, and to move to and work in any province",x:["The right to a driver's licence","The right to free public transit","The right to travel abroad for free"]},
{u:3,l:2,t:"Laws & Documents",d:2,q:"Why does section 6 exist?",a:"To prevent provinces from treating Canadians from other provinces as outsiders, supporting one unified country and labour market",x:["To regulate immigration","To fund highways","To protect provincial borders"]},
{u:3,l:2,t:"Laws & Documents",d:2,q:"Which Charter rights cannot be overridden by the notwithstanding clause, according to Lesson 2?",a:"Democratic rights (s.3–5) and mobility rights (s.6)",x:["Fundamental freedoms (s.2)","Legal rights (s.7–14)","Equality rights (s.15)"]},
{u:3,l:2,t:"Laws & Documents",d:2,q:"Why are legal rights (s.7–14) described as the largest and most litigated cluster?",a:"They cover almost every stage of contact with the justice system, from police contact through trial to sentencing",x:["They are the only rights police must obey","They were added in 1985","They apply only to citizens"]},
{u:3,l:2,t:"Laws & Documents",d:2,q:"What does section 11 include?",a:"Rights on being charged, including trial within a reasonable time and the presumption of innocence",x:["The right to vote","Freedom from unreasonable search","The right to an interpreter"]},
{u:3,l:2,t:"Theories & Concepts",d:2,q:"What responsibility corresponds to the right to vote?",a:"To vote (or choose not to) as an informed citizen and to respect the outcome of a fair election",x:["To run for office","To pay a voting fee","To serve on a jury"]},
{u:3,l:2,t:"Theories & Concepts",d:2,q:"What responsibility corresponds to the right to a jury trial?",a:"To serve on a jury if summoned",x:["To hire a lawyer","To attend all trials","To vote in elections"]},
{u:3,l:2,t:"Theories & Concepts",d:2,q:"What responsibility corresponds to freedom of expression?",a:"To exercise it without infringing on others' Charter rights, such as equality or security",x:["To publish a newspaper","To agree with the government","To speak only in English or French"]},
{u:3,l:2,t:"Theories & Concepts",d:2,q:"What responsibility corresponds to legal rights (s.7–14)?",a:"To respect the legal rights of others, including the presumption of innocence, even for people accused of serious crimes",x:["To report all crimes","To avoid contact with police","To become a lawyer"]},
{u:3,l:2,t:"Laws & Documents",d:3,q:"A city bans a religious group from holding services. Which Charter section is engaged?",a:"Section 2(a) — freedom of conscience and religion",x:["Section 6 — mobility","Section 8 — search and seizure","Section 11(b) — reasonable time"]},
{u:3,l:2,t:"Laws & Documents",d:3,q:"Police search a car without a warrant or grounds. Which section and case apply?",a:"Section 8 and Hunter v. Southam",x:["Section 12 and R. v. Jordan","Section 2(b) and Big M Drug Mart","Section 6 and Oakes"]},
{u:3,l:2,t:"Laws & Documents",d:3,q:"An accused waits four years for a trial with no good reason. Which section and case apply?",a:"Section 11(b) and R. v. Jordan",x:["Section 8 and Hunter v. Southam","Section 12 and Big M Drug Mart","Section 13 and Oakes"]},
{u:3,l:2,t:"Modern Connections",d:3,q:"A province bars workers from Alberta from applying for jobs in Ontario. Which section is engaged?",a:"Section 6 — mobility rights",x:["Section 3 — democratic rights","Section 2(d) — association","Section 7 — security of the person"]},
{u:3,l:2,t:"Laws & Documents",d:3,q:"A government tries to postpone a federal election for a seventh year. Which section forbids this, and can section 33 override it?",a:"Section 4; no — democratic rights cannot be overridden by section 33",x:["Section 6; yes","Section 2; yes","Section 15; no"]},
{u:3,l:2,t:"Laws & Documents",d:3,q:"An arrested person is not told why they were arrested and is refused a lawyer. Which section is violated?",a:"Section 10",x:["Section 8","Section 12","Section 14"]},
{u:3,l:2,t:"Laws & Documents",d:3,q:"A law imposes a punishment so severe it shocks the conscience. Which section is engaged?",a:"Section 12 — cruel and unusual punishment",x:["Section 7","Section 9","Section 13"]},
{u:3,l:2,t:"Laws & Documents",d:3,q:"A witness who does not speak English is denied translation at trial. Which section is violated?",a:"Section 14",x:["Section 23","Section 16","Section 13"]},
{u:3,l:2,t:"Cases & Rulings",d:3,q:"A federal law forces all businesses to close on Sunday for religious reasons. Which case is the direct precedent?",a:"R. v. Big M Drug Mart Ltd.",x:["Hunter v. Southam","R. v. Jordan","Andrews v. Law Society"]},
{u:3,l:2,t:"Laws & Documents",d:3,q:"A protester's speech is limited by a law. Which two sections will a court analyze, in order?",a:"Section 2(b), then section 1 (Oakes test)",x:["Section 33, then section 2(b)","Section 6, then section 15","Section 52, then section 7"]},
{u:3,l:2,t:"Laws & Documents",d:4,q:"Why might legal rights be the most frequently litigated part of the Charter?",a:"Every criminal case involves police and courts, so there are many opportunities for these rights to be engaged",x:["Because they are the only enforceable rights","Because they were added last","Because they apply only to lawyers"]},
{u:3,l:2,t:"Laws & Documents",d:4,q:"Why did the Charter's framers place democratic and mobility rights beyond the reach of section 33?",a:"So Parliament could not suspend elections indefinitely or fragment the country, even with an override",x:["Because those rights were considered unimportant","Because the provinces demanded it","Because courts cannot interpret them"]},
{u:3,l:2,t:"Modern Connections",d:4,q:"How does section 1 connect Unit 1's R. v. Oakes to Unit 3?",a:"Section 1 is the source of the Oakes test — the two-part framework for deciding whether a violation is justified",x:["Section 1 created the notwithstanding clause","Oakes abolished section 1","Section 1 applies only to drug cases"]},
{u:3,l:2,t:"Laws & Documents",d:4,q:"Why does the course pair every Charter right with a 'corresponding responsibility'?",a:"The Ontario curriculum asks students to consider the implications of rights AND responsibilities for different groups, since rights work only if citizens participate",x:["Because rights are earned by meeting responsibilities","Because responsibilities are written in the Charter","Because responsibilities can override rights"]},
{u:3,l:2,t:"Theories & Concepts",d:4,q:"When might exercising freedom of expression come into tension with someone else's rights?",a:"When speech infringes on another person's equality or security rights",x:["Never — expression is absolute","Only when speaking in Parliament","Only during elections"]},
{u:3,l:2,t:"Cases & Rulings",d:4,q:"Why might a right 'feel very different in practice' depending on whether others take their responsibilities seriously?",a:"A jury trial, for example, depends on citizens actually serving when summoned",x:["Because rights expire if unused","Because responsibilities are optional","Because courts ignore unpopular rights"]},

/* ---------- Lesson 3: The Charter, Section by Section (Part 2) ---------- */
{u:3,l:3,t:"Cases & Rulings",d:1,q:"Which 1989 case was the Supreme Court's first major interpretation of section 15?",a:"Andrews v. Law Society of British Columbia",x:["R. v. Big M Drug Mart","R. v. Sparrow","Hunter v. Southam"]},
{u:3,l:3,t:"Laws & Documents",d:1,q:"Which Charter sections establish English and French as official languages?",a:"Sections 16–20",x:["Sections 3–5","Sections 7–14","Section 23"]},
{u:3,l:3,t:"Laws & Documents",d:1,q:"Which Charter section guarantees minority-language education rights?",a:"Section 23",x:["Section 16","Section 25","Section 15"]},
{u:3,l:3,t:"Laws & Documents",d:1,q:"Which Charter section states that nothing in the Charter takes away from existing Aboriginal, treaty, or other rights?",a:"Section 25",x:["Section 35","Section 15","Section 33"]},
{u:3,l:3,t:"Laws & Documents",d:1,q:"Which section of the Constitution Act, 1982 recognizes and affirms existing Aboriginal and treaty rights?",a:"Section 35",x:["Section 25","Section 52","Section 32"]},
{u:3,l:3,t:"Cases & Rulings",d:1,q:"Which case set the framework for interpreting section 35 rights, using an Indigenous fishing right?",a:"R. v. Sparrow",x:["Delgamuukw v. British Columbia","Andrews v. Law Society","R. v. Ewanchuk"]},
{u:3,l:3,t:"Laws & Documents",d:1,q:"Which Charter section defines who the Charter applies to?",a:"Section 32",x:["Section 34","Section 1","Section 52"]},
{u:3,l:3,t:"Laws & Documents",d:1,q:"What does section 34 of the Charter do?",a:"Confirms the short title: 'Canadian Charter of Rights and Freedoms'",x:["Sets out equality rights","Creates the notwithstanding clause","Lists the official languages"]},
{u:3,l:3,t:"Laws & Documents",d:1,q:"In what year did section 15 come into force?",a:"1985",x:["1982","1989","1960"]},
{u:3,l:3,t:"Laws & Documents",d:1,q:"Which part of the Constitution Act, 1982 contains the amending formula?",a:"Part V",x:["Part I","Part II","Section 33"]},
{u:3,l:3,t:"Laws & Documents",d:2,q:"Which grounds of discrimination are listed in section 15?",a:"Race, national or ethnic origin, colour, religion, sex, age, or mental or physical disability",x:["Income, education, and occupation","Province of residence and language only","Political party and union membership"]},
{u:3,l:3,t:"Laws & Documents",d:2,q:"Why is the section 15 list described as 'not exhaustive'?",a:"Courts have 'read in' additional grounds, like sexual orientation, that were not in the original text",x:["Because Parliament adds grounds every year","Because the list was never finished","Because it applies only to the listed groups"]},
{u:3,l:3,t:"Laws & Documents",d:2,q:"Why did section 15 come into force three years after the rest of the Charter?",a:"Governments were given extra time to review existing laws for compliance first",x:["It was added by a later amendment","The courts delayed it","The provinces opposed it"]},
{u:3,l:3,t:"Laws & Documents",d:2,q:"Why do language rights exist in the Charter?",a:"Language was central to Confederation and protects French-speaking minorities outside Quebec and the English-speaking minority within it",x:["To require every Canadian to be bilingual","To ban other languages","To regulate immigration"]},
{u:3,l:3,t:"Laws & Documents",d:2,q:"What has section 23 generated significant litigation over?",a:"What level of French-language schooling provinces must actually provide, not just permit",x:["Whether English is an official language","Who may sit in the Senate","Whether Quebec can leave Canada"]},
{u:3,l:3,t:"Laws & Documents",d:2,q:"Which sections can section 33 override?",a:"Sections 2 and 7–15 — fundamental freedoms, legal rights, and equality rights",x:["Sections 3–6 and 16–23","Every section of the Charter","Only section 1"]},
{u:3,l:3,t:"Laws & Documents",d:2,q:"Which rights can section 33 NOT override?",a:"Democratic rights (s.3–5), mobility rights (s.6), and language rights (s.16–23)",x:["Fundamental freedoms (s.2)","Legal rights (s.7–14)","Equality rights (s.15)"]},
{u:3,l:3,t:"Laws & Documents",d:2,q:"How does the use of section 1 compare to the use of section 33?",a:"Section 1 is used constantly in almost every Charter case; section 33 is used rarely but deliberately",x:["Both are used in every case","Section 33 is used constantly; section 1 rarely","Neither has ever been used"]},
{u:3,l:3,t:"Laws & Documents",d:2,q:"Who does the Charter apply to under section 32?",a:"Parliament, the federal government, and every provincial legislature and government — not private individuals or companies directly",x:["Everyone, including private companies","Only the federal government","Only the courts"]},
{u:3,l:3,t:"Laws & Documents",d:2,q:"What does the amending formula typically require?",a:"Agreement from Parliament and at least seven provinces representing 50% of the population",x:["A simple majority in the House of Commons","Unanimous consent of all provinces","Approval by the Supreme Court"]},
{u:3,l:3,t:"Theories & Concepts",d:2,q:"What responsibility corresponds to equality rights?",a:"To treat others equally in daily life, not only to expect equal treatment from the law",x:["To file a complaint when discriminated against","To avoid all comparisons","To vote in every election"]},
{u:3,l:3,t:"Theories & Concepts",d:2,q:"What responsibility corresponds to Aboriginal and treaty rights, according to Lesson 3?",a:"Governments must consult meaningfully with Indigenous peoples before acting in ways that affect their rights",x:["Indigenous peoples must give up title","Provinces must fund all schools","Courts must ignore oral history"]},
{u:3,l:3,t:"Theories & Concepts",d:2,q:"Under section 1, who carries the burden of proof to justify a limit on a right?",a:"The state, not the individual",x:["The individual whose right was limited","The judge","A jury"]},
{u:3,l:3,t:"Laws & Documents",d:2,q:"How does section 25 differ from section 35?",a:"Section 25 is a shield within the Charter protecting Indigenous rights from being diminished; section 35 directly recognizes and affirms those rights in a separate part of the Constitution Act",x:["They are identical","Section 25 abolishes treaty rights; section 35 restores them","Section 35 is part of the Charter; section 25 is not"]},
{u:3,l:3,t:"Laws & Documents",d:3,q:"A provincial law denies benefits to people based on sexual orientation, which is not listed in section 15. Can section 15 still apply?",a:"Yes — courts have read in grounds like sexual orientation",x:["No — only listed grounds count","Only if section 33 is invoked","Only in Quebec"]},
{u:3,l:3,t:"Laws & Documents",d:3,q:"A French-speaking family in Ontario demands a French-language school for their children. Which section applies?",a:"Section 23",x:["Section 16","Section 25","Section 6"]},
{u:3,l:3,t:"Laws & Documents",d:3,q:"A legislature invokes section 33 to override a court ruling on equality rights. Is that allowed?",a:"Yes — section 15 is among the sections section 33 can override",x:["No — section 15 is protected from section 33","Only with Supreme Court approval","Only for one year"]},
{u:3,l:3,t:"Laws & Documents",d:3,q:"A legislature tries to use section 33 to cancel French-language services. Is that allowed?",a:"No — language rights (s.16–23) cannot be overridden by section 33",x:["Yes — any section can be overridden","Yes — for up to five years","Only if the federal government agrees"]},
{u:3,l:3,t:"Laws & Documents",d:3,q:"A private company discriminates against an employee. Can the employee sue the company directly under the Charter?",a:"No — under section 32 the Charter applies to governments, not private companies directly",x:["Yes — the Charter applies to everyone","Only under section 33","Only if the company is in Quebec"]},
{u:3,l:3,t:"Cases & Rulings",d:3,q:"A government argues a law affecting Indigenous fishing is justified. Which case provides the framework for that analysis?",a:"R. v. Sparrow",x:["Andrews v. Law Society","R. v. Oakes","Hunter v. Southam"]},
{u:3,l:3,t:"Laws & Documents",d:3,q:"Parliament and six provinces representing 40% of the population want to amend the Charter. Can they?",a:"No — the formula typically requires at least seven provinces with 50% of the population",x:["Yes — six provinces is enough","Yes — Parliament alone can amend it","Only with Senate approval"]},
{u:3,l:3,t:"Laws & Documents",d:3,q:"A government argues its limit on a right is justified but offers no evidence. Under section 1, what happens?",a:"The limit likely fails — the burden of proof is on the state",x:["The individual must prove the limit is unjustified","The court must accept the government's word","The notwithstanding clause applies automatically"]},
{u:3,l:3,t:"Laws & Documents",d:4,q:"Why might the Charter's authors have allowed section 33 to override some rights but not others?",a:"They protected the basic machinery of democracy, national unity, and the Confederation language bargain, while leaving room for legislative override elsewhere",x:["They thought equality rights were unimportant","They wanted to make the Charter easy to repeal","They were forced by the courts"]},
{u:3,l:3,t:"Laws & Documents",d:4,q:"How do sections 25 and 35 connect to Delgamuukw and Sparrow from Unit 2?",a:"They are the constitutional foundation those cases interpret — Aboriginal title and the framework for section 35 rights",x:["They overturned both cases","They apply only to fishing","They were created by those cases"]},
{u:3,l:3,t:"Laws & Documents",d:4,q:"Why is the amending formula 'deliberately difficult'?",a:"To prevent a single government or narrow majority from changing fundamental rights easily",x:["To make the Charter permanent and unchangeable","To give the Senate more power","Because the courts demanded it"]},
{u:3,l:3,t:"Theories & Concepts",d:4,q:"Compare the 'corresponding responsibility' for minority language rights with that for equality rights.",a:"Language rights require institutions to actively support access; equality rights require individuals to treat others equally in daily life",x:["Both require only government action","Both apply only to Quebec","Neither has a responsibility"]},
{u:3,l:3,t:"Laws & Documents",d:4,q:"Why does the course call section 15's three-year delay significant?",a:"It shows governments were given time to bring existing laws into line before equality claims could be brought",x:["It shows equality was never intended to be protected","It shows the provinces vetoed section 15","It shows section 15 was never passed"]},
{u:3,l:3,t:"Laws & Documents",d:4,q:"How does section 32 relate to the Unit 1 concept that the Charter 'binds every level of government'?",a:"Section 32 is the text that makes the Charter apply to federal, provincial, and territorial governments alike",x:["Section 32 limits the Charter to the federal government","Section 32 extends the Charter to private companies","Section 32 is the notwithstanding clause"]},

/* ---------- Lesson 4: The Universal Declaration of Human Rights ---------- */
{u:3,l:4,t:"People & Institutions",d:1,q:"Who chaired the UN Commission on Human Rights that drafted the UDHR?",a:"Eleanor Roosevelt",x:["René Cassin","Charles Malik","John Peters Humphrey"]},
{u:3,l:4,t:"People & Institutions",d:1,q:"Which Canadian prepared the initial blueprint for the UDHR?",a:"John Peters Humphrey",x:["Philippe Kirsch","Roméo Dallaire","Lester Pearson"]},
{u:3,l:4,t:"People & Institutions",d:1,q:"Who wrote the first full draft of the UDHR?",a:"René Cassin of France",x:["Charles Malik of Lebanon","Peng Chung Chang of China","Eleanor Roosevelt"]},
{u:3,l:4,t:"People & Institutions",d:1,q:"Which drafter served as rapporteur of the UDHR committee?",a:"Charles Malik of Lebanon",x:["René Cassin","P.C. Chang","Lakshmi Menon"]},
{u:3,l:4,t:"People & Institutions",d:1,q:"Which drafter from China was vice-chair of the UDHR committee?",a:"Peng Chung Chang",x:["Charles Malik","John Humphrey","René Cassin"]},
{u:3,l:4,t:"Laws & Documents",d:1,q:"On what date was the UDHR adopted?",a:"December 10, 1948",x:["June 26, 1945","April 17, 1982","July 17, 1998"]},
{u:3,l:4,t:"Laws & Documents",d:1,q:"How many articles does the UDHR contain?",a:"30",x:["10","52","100"]},
{u:3,l:4,t:"Laws & Documents",d:1,q:"Where was the UDHR adopted?",a:"Paris",x:["New York","Geneva","The Hague"]},
{u:3,l:4,t:"Vocabulary",d:1,q:"What is 'cultural relativism'?",a:"The idea that human rights standards should be judged relative to each culture's own values, not one universal standard",x:["The idea that all cultures are identical","The belief that Western values are superior","The view that rights come only from treaties"]},
{u:3,l:4,t:"Laws & Documents",d:1,q:"Which two covenants turned the UDHR's principles into binding international law?",a:"The International Covenant on Civil and Political Rights and the International Covenant on Economic, Social and Cultural Rights",x:["The Rome Statute and the Geneva Conventions","The Charter and the Bill of Rights","The Magna Carta and the Cyrus Cylinder"]},
{u:3,l:4,t:"People & Institutions",d:1,q:"Which Indian delegate pushed back against Western-only framing during UDHR drafting?",a:"Lakshmi Menon",x:["Eleanor Roosevelt","Charles Malik","René Cassin"]},
{u:3,l:4,t:"Laws & Documents",d:2,q:"How did the UDHR vote break down?",a:"48 in favour, none against, 8 abstentions, 2 not voting",x:["58 in favour, none against","30 in favour, 28 against","Unanimous with no abstentions"]},
{u:3,l:4,t:"Laws & Documents",d:2,q:"Which states abstained from the UDHR vote?",a:"The Soviet bloc and South Africa, among others",x:["The United States and Canada","France and Lebanon","China and India"]},
{u:3,l:4,t:"Laws & Documents",d:2,q:"How did René Cassin describe the structure of the UDHR?",a:"Like a Greek temple: a foundation (Articles 1–2), four columns (families of rights), and a pediment (Articles 28–30)",x:["Like a pyramid with the state at the top","Like a ladder from least to most important","Like a wheel with no centre"]},
{u:3,l:4,t:"Laws & Documents",d:2,q:"Is the UDHR directly legally binding?",a:"No — it is a General Assembly resolution, but it has become the moral and legal foundation for later binding treaties",x:["Yes — it is enforced by the ICC","Yes — it is part of every constitution","No — it has no legal significance at all"]},
{u:3,l:4,t:"Laws & Documents",d:2,q:"Why was the UDHR a first in international law?",a:"It was the first time the international community agreed that individuals, not just states, hold rights that matter internationally",x:["It was the first treaty ever signed","It created the United Nations","It ended the Second World War"]},
{u:3,l:4,t:"Theories & Concepts",d:2,q:"What is the 'westernization critique' of the UDHR?",a:"That it reflects primarily Western liberal values rather than genuinely universal ones, since it was drafted right after European colonialism",x:["That it was written only in English","That it has too many articles","That it ignores civil rights"]},
{u:3,l:4,t:"Theories & Concepts",d:2,q:"What is the strongest counter-argument to the westernization critique?",a:"The drafting committee was genuinely international, and delegates from India and China pushed back against Western-only framing",x:["Western values are objectively correct","The UDHR was written by the Soviet Union","No Western countries voted for it"]},
{u:3,l:4,t:"Laws & Documents",d:2,q:"Which later treaties named in the CLN4U curriculum trace their authority to the UDHR?",a:"The Convention on the Rights of the Child, the Convention on the Rights of Persons with Disabilities, and the UN Declaration on the Rights of Indigenous Peoples",x:["The Rome Statute, NATO treaty, and NAFTA","The Magna Carta, Bill of Rights, and Charter","The Kyoto Protocol and Paris Agreement"]},
{u:3,l:4,t:"Theories & Concepts",d:2,q:"What does signing or ratifying a treaty commit a country to?",a:"An international commitment, but enforcement varies from binding tribunals to reputational pressure",x:["Automatic enforcement by the ICC","Nothing at all","Changing its constitution immediately"]},
{u:3,l:4,t:"Laws & Documents",d:2,q:"How long did it take to draft the UDHR, and how many working sessions?",a:"Under two years, with eighty-five working sessions",x:["Ten years, with twelve sessions","One week, with three sessions","Five years, with five hundred sessions"]},
{u:3,l:4,t:"Laws & Documents",d:2,q:"Which categories of rights are covered in the UDHR's 30 articles?",a:"Both civil and political rights and economic, social, and cultural rights",x:["Only civil and political rights","Only economic rights","Only rights of states"]},
{u:3,l:4,t:"Theories & Concepts",d:3,q:"A government argues that a human rights standard shouldn't apply to it because its culture has different values. Which concept is it invoking?",a:"Cultural relativism",x:["Universalism","Complementarity","Situatedness"]},
{u:3,l:4,t:"Laws & Documents",d:3,q:"A country signs a human rights treaty but violates it with no consequences. What does this illustrate about treaties?",a:"Enforcement mechanisms vary widely — some rely on little more than reputational pressure",x:["Treaties are automatically enforced","Signing a treaty changes domestic law immediately","Treaties are legally meaningless"]},
{u:3,l:4,t:"Laws & Documents",d:3,q:"Someone claims the UDHR was simply imposed by Western powers. Which fact best answers this?",a:"Drafters from France, Lebanon, China, Canada, and India all shaped the text",x:["Only the United States voted for it","Eleanor Roosevelt wrote it alone","It was adopted in Washington"]},
{u:3,l:4,t:"Theories & Concepts",d:3,q:"A lawyer wants to cite a binding international obligation on Canada for civil and political rights. Which document should she cite?",a:"The International Covenant on Civil and Political Rights",x:["The UDHR itself","The Cyrus Cylinder","The French Declaration of 1789"]},
{u:3,l:4,t:"Laws & Documents",d:3,q:"A state claims how it treats its own citizens is 'purely its own business.' Which 1948 development contradicts this?",a:"The UDHR made how a government treats its people a matter of international concern",x:["The founding of NATO","The Nuremberg trials","The Magna Carta"]},
{u:3,l:4,t:"Modern Connections",d:3,q:"Using Cassin's temple image, where would 'dignity and equality' sit?",a:"In the foundation (Articles 1–2)",x:["In the pediment (Articles 28–30)","In one of the four columns","Outside the temple"]},
{u:3,l:4,t:"Modern Connections",d:3,q:"Using Cassin's temple image, what do Articles 28–30 describe?",a:"The conditions needed to realize the rights and their limits",x:["The foundation of dignity","The right to education","The structure of the United Nations"]},
{u:3,l:4,t:"Theories & Concepts",d:4,q:"Does the diversity of the drafting committee fully answer the westernization critique? What remains debatable?",a:"It shows the text was not simply handed down by the West, but the post-colonial context and the emphasis on individual rights can still be questioned",x:["Yes — the critique is entirely false","No — the committee was entirely Western","The question is irrelevant to the UDHR"]},
{u:3,l:4,t:"Laws & Documents",d:4,q:"Why does the Cold War tension from Lesson 1 appear in the UDHR vote?",a:"The Soviet bloc abstained, reflecting the East-West divide over civil/political versus economic/social rights",x:["The Soviet Union wrote the UDHR","The United States abstained","There was no tension in 1948"]},
{u:3,l:4,t:"Laws & Documents",d:4,q:"How does the UDHR being non-binding relate to its later influence?",a:"Though a resolution rather than a treaty, it became the foundation that the binding covenants and later treaties built on",x:["Being non-binding made it irrelevant","It was later made binding by the Charter","Only binding documents have influence"]},
{u:3,l:4,t:"Laws & Documents",d:4,q:"How does the UDHR connect to the Unit 1 question of where law's authority comes from?",a:"It reflects a natural-law idea that individuals hold rights above any single government's enactments",x:["It is a purely positivist document","It says rights come only from the state","It rejects the idea of universal rights"]},
{u:3,l:4,t:"Laws & Documents",d:4,q:"Why is Canada's role in the UDHR and later treaties significant for the CLN4U curriculum?",a:"The curriculum requires understanding what Canada's signing of international human rights treaties actually commits it to",x:["Canada never signed any human rights treaties","Canada wrote the UDHR alone","Canada is exempt from the UDHR"]},

/* ---------- Lesson 5: Universalism vs Relativism ---------- */
{u:3,l:5,t:"Vocabulary",d:1,q:"What is 'situatedness'?",a:"The idea that our moral judgments are shaped by the specific cultural, historical, and social position we occupy",x:["The idea that all cultures are equally valid","The belief that rights are universal","A rule for international treaties"]},
{u:3,l:5,t:"Theories & Concepts",d:1,q:"According to Lesson 5, we don't judge from nowhere — we judge from…",a:"Somewhere",x:["Everywhere","Nowhere","The courtroom"]},
{u:3,l:5,t:"Theories & Concepts",d:1,q:"Which practice is Tier 1 on the lesson's spectrum?",a:"Infant ear piercing",x:["Male circumcision","Female genital cutting","Tattooing"]},
{u:3,l:5,t:"Theories & Concepts",d:1,q:"Which practice is Tier 2 on the lesson's spectrum?",a:"Male circumcision",x:["Infant ear piercing","Female genital cutting","Infant baptism"]},
{u:3,l:5,t:"Theories & Concepts",d:1,q:"Which practice is Tier 3 on the lesson's spectrum?",a:"Female genital cutting",x:["Male circumcision","Infant ear piercing","Arranged marriage"]},
{u:3,l:5,t:"People & Institutions",d:1,q:"Which two international bodies classify female genital cutting as a human rights violation?",a:"The WHO and the UN",x:["The ICC and the ICJ","NATO and the EU","The Supreme Court and the Senate"]},
{u:3,l:5,t:"Vocabulary",d:1,q:"What is the Jewish term for religious male circumcision?",a:"Brit milah",x:["Khitan","Bar mitzvah","Kashrut"]},
{u:3,l:5,t:"Vocabulary",d:1,q:"What is the Islamic term for religious male circumcision?",a:"Khitan",x:["Brit milah","Halal","Hajj"]},
{u:3,l:5,t:"Vocabulary",d:1,q:"What are bioethicists who argue infant circumcision violates bodily autonomy sometimes called?",a:"Intactivists",x:["Relativists","Universalists","Positivists"]},
{u:3,l:5,t:"Theories & Concepts",d:2,q:"Does recognizing situatedness mean abandoning moral judgment?",a:"No — it means pausing to ask whether a reaction is based on careful reasoning or simply on what feels familiar",x:["Yes — all judgments are equally valid","Yes — only courts may judge","No — it means judging more harshly"]},
{u:3,l:5,t:"Theories & Concepts",d:2,q:"Why does Lesson 5 use a spectrum of three examples rather than one?",a:"Treating every example as equally debatable would misrepresent what international law actually says",x:["Because three is a lucky number","Because students need more homework","Because all three are illegal"]},
{u:3,l:5,t:"Theories & Concepts",d:2,q:"What two questions should be asked about each example?",a:"What is my first reaction, and what specific reasoning is that reaction actually based on?",x:["Is it legal in Canada, and is it legal in the U.S.?","Who does it, and when?","Is it old, and is it popular?"]},
{u:3,l:5,t:"Theories & Concepts",d:2,q:"What is the international law standing of infant ear piercing?",a:"Not classified as a human rights concern by any major body — no lasting harm, broadly a benign tradition",x:["Classified as a violation by the WHO","Banned by the UN","Debated by the ICC"]},
{u:3,l:5,t:"Theories & Concepts",d:2,q:"What is the international law standing of male circumcision?",a:"Not classified as a violation by the WHO or UN; genuinely debated among ethicists without legal consensus on harm",x:["Classified as a human rights violation","Required by international law","Never discussed by ethicists"]},
{u:3,l:5,t:"Theories & Concepts",d:2,q:"Why does the WHO and UN classify female genital cutting as a human rights violation?",a:"Documented physical and psychological harm, no medical benefit, and lifelong health consequences",x:["Because it is unfamiliar to Western observers","Because it is practiced in Africa","Because it is a religious practice"]},
{u:3,l:5,t:"Theories & Concepts",d:2,q:"Why is it 'instructive' that male circumcision is common as a secular practice in the United States?",a:"It breaks the assumption that this is simply a non-Western practice being judged by the West",x:["It proves the practice is harmful","It shows the U.S. has no cultural practices","It makes the practice illegal elsewhere"]},
{u:3,l:5,t:"Theories & Concepts",d:2,q:"What three factors does international law use to draw its line between practices?",a:"Documented physical harm, whether there is a recognized medical benefit, and whether the harm is permanent or reversible",x:["Popularity, age, and religion","Cost, location, and tradition","Familiarity, legality in Canada, and media coverage"]},
{u:3,l:5,t:"Theories & Concepts",d:2,q:"What is the anthropological critique of outside condemnation of female genital cutting?",a:"It can echo colonial-era moral policing, and lasting change comes from community-led education rather than external pressure",x:["Outside condemnation is always effective","The practice has medical benefits","International law should ignore the practice"]},
{u:3,l:5,t:"Theories & Concepts",d:2,q:"How does Lesson 5 connect to the 'legal perspective' concept in the course?",a:"Considering fairness and justice requires first understanding whose fairness and whose justice is being assumed",x:["Legal perspective means ignoring culture","Fairness is the same everywhere","Only lawyers can judge culture"]},
{u:3,l:5,t:"Theories & Concepts",d:2,q:"How does Lesson 5 relate to Lesson 4's westernization critique?",a:"It applies the same question at the level of individual cultural practices rather than international documents",x:["It rejects the westernization critique entirely","It is unrelated to Lesson 4","It proves the UDHR is Western"]},
{u:3,l:5,t:"Theories & Concepts",d:3,q:"A practice causes no lasting harm and is a benign family tradition, yet an observer feels uncomfortable. According to Lesson 5, what is driving the discomfort?",a:"Unfamiliarity, not a consistent principle",x:["Documented harm","International law","Medical evidence"]},
{u:3,l:5,t:"Theories & Concepts",d:3,q:"A practice has documented lifelong harm, no medical benefit, and is permanent. How does international law treat it?",a:"As a human rights violation, not as an equally valid custom",x:["As a benign tradition","As a matter for debate only","As protected cultural expression"]},
{u:3,l:5,t:"Theories & Concepts",d:3,q:"A student's first reaction to an unfamiliar custom is disgust. What does Lesson 5 ask the student to do next?",a:"Ask what specific reasoning the reaction is based on, using the three factors",x:["Trust the instinct and condemn it","Ignore the practice entirely","Assume the practice is harmful"]},
{u:3,l:5,t:"Theories & Concepts",d:3,q:"Which Lesson 5 principle explains why two students from different backgrounds react differently to the same practice?",a:"Situatedness",x:["Complementarity","Indivisibility","Procedural justice"]},
{u:3,l:5,t:"Theories & Concepts",d:3,q:"An outsider sees a mainstream Canadian practice as strange. What point is Lesson 5 making with this exercise?",a:"Every culture has practices that look odd from outside — familiarity shapes judgment",x:["Canadian practices are always correct","Outsiders can never understand Canada","Canadian law is universal"]},
{u:3,l:5,t:"Theories & Concepts",d:3,q:"A medical ethicist argues a child should wait until they can consent to a body modification with no medical consensus on harm. Which tier does this debate belong to?",a:"Tier 2 — male circumcision",x:["Tier 1 — infant ear piercing","Tier 3 — female genital cutting","None of the tiers"]},
{u:3,l:5,t:"Theories & Concepts",d:3,q:"A government wants to end a harmful practice. Which approach does the anthropological critique favour?",a:"Community-led education",x:["External legal pressure alone","Military intervention","Ignoring the practice"]},
{u:3,l:5,t:"Theories & Concepts",d:4,q:"Using only the three factors (harm, medical benefit, permanence), why does international law treat Tier 3 differently from Tiers 1 and 2?",a:"Tier 3 has documented lasting harm, no medical benefit, and permanent consequences; Tiers 1 and 2 lack documented lasting harm or remain genuinely debated",x:["Because Tier 3 is practiced in non-Western countries","Because Tiers 1 and 2 are religious","Because Tier 3 is the most unfamiliar to Canadians"]},
{u:3,l:5,t:"Theories & Concepts",d:4,q:"Is community-led change or external legal pressure more likely to change a deeply-held practice? What does the lesson suggest?",a:"It may depend on the practice; community-led education is often more lasting, though international law still sets a clear line on harm",x:["External pressure always works","Community-led change never works","Neither can ever change a practice"]},
{u:3,l:5,t:"Theories & Concepts",d:4,q:"How does situatedness refine, rather than reject, universalism?",a:"It asks us to check that our universal judgments rest on consistent principles like documented harm, not on familiarity",x:["It proves that no standards are universal","It replaces law with personal feeling","It makes all practices equally acceptable"]},
{u:3,l:5,t:"People & Institutions",d:4,q:"How does Lesson 5 connect to Unit 1's Lesson 1 question 'Whose morals should laws be based on?'",a:"Both ask whose values are being assumed when law and judgment are applied across different communities",x:["Both conclude the majority always decides","Both reject the idea of morals","Both concern only Canadian law"]},
{u:3,l:5,t:"Theories & Concepts",d:4,q:"Why does the lesson say treating all three tiers as 'equally debatable' would be a mistake?",a:"International law draws a principled line based on harm — pretending otherwise would misrepresent the law and the evidence",x:["Because only Tier 1 is debatable","Because debate is never appropriate","Because all three are banned"]},

/* ---------- Lesson 6: Mandela & Rwanda ---------- */
{u:3,l:6,t:"Vocabulary",d:1,q:"What was apartheid?",a:"A legal system of racial segregation enforced in South Africa from 1948 to the early 1990s",x:["A UN peacekeeping mission","A truth commission","A civil war in Rwanda"]},
{u:3,l:6,t:"People & Institutions",d:1,q:"Nelson Mandela was a leader of which organization?",a:"The African National Congress",x:["The United Nations","The Truth and Reconciliation Commission","The Rwandan Patriotic Front"]},
{u:3,l:6,t:"People & Institutions",d:1,q:"How many years did Mandela spend in prison?",a:"27",x:["14","10","35"]},
{u:3,l:6,t:"People & Institutions",d:1,q:"On which island was Mandela imprisoned for most of his sentence?",a:"Robben Island",x:["Alcatraz","Devil's Island","Ellis Island"]},
{u:3,l:6,t:"People & Institutions",d:1,q:"With whom did Mandela negotiate the end of apartheid and share the 1993 Nobel Peace Prize?",a:"F.W. de Klerk",x:["Desmond Tutu","Paul Rusesabagina","Roméo Dallaire"]},
{u:3,l:6,t:"People & Institutions",d:1,q:"In what year was Mandela elected South Africa's first Black president?",a:"1994",x:["1990","1962","1948"]},
{u:3,l:6,t:"People & Institutions",d:1,q:"Which Canadian general commanded the UN peacekeeping force in Rwanda?",a:"Roméo Dallaire",x:["Lester Pearson","Philippe Kirsch","John Humphrey"]},
{u:3,l:6,t:"Cases & Rulings",d:1,q:"Approximately how many people were killed in the Rwandan genocide?",a:"800,000",x:["80,000","8,000","8 million"]},
{u:3,l:6,t:"Modern Connections",d:1,q:"Which 2004 film depicts hotel manager Paul Rusesabagina sheltering refugees?",a:"Hotel Rwanda",x:["Invictus","The Mauritanian","Devil's Knot"]},
{u:3,l:6,t:"Modern Connections",d:1,q:"Which 2009 film uses the 1995 Rugby World Cup to show Mandela's nation-building?",a:"Invictus",x:["Hotel Rwanda","The Skin We're In","West of Memphis"]},
{u:3,l:6,t:"People & Institutions",d:1,q:"What body did Mandela's government create to offer amnesty in exchange for full disclosure of apartheid-era crimes?",a:"The Truth and Reconciliation Commission",x:["The International Criminal Court","The Special Investigations Unit","The Miscarriage of Justice Review Commission"]},
{u:3,l:6,t:"Cases & Rulings",d:1,q:"Over roughly how many days did the Rwandan genocide take place?",a:"100",x:["10","365","1,000"]},
{u:3,l:6,t:"Cases & Rulings",d:2,q:"What event on April 6, 1994 triggered the Rwandan genocide?",a:"A plane carrying Rwanda's president was shot down",x:["A UN resolution was passed","Mandela was released","A peace treaty was signed"]},
{u:3,l:6,t:"Cases & Rulings",d:2,q:"Who were the targets of the Rwandan genocide?",a:"Tutsi civilians and moderate Hutu",x:["UN peacekeepers only","Belgian colonists","Hutu extremists"]},
{u:3,l:6,t:"Cases & Rulings",d:2,q:"Where did the Hutu/Tutsi division originate, according to the course?",a:"Colonial-era authorities divided the population into identity categories that hardened after independence",x:["Ancient religious conflict","A 1994 referendum","The UN's partition plan"]},
{u:3,l:6,t:"Cases & Rulings",d:2,q:"Why did the UN peacekeeping force in Rwanda fail to stop the killing?",a:"It was small, was not reinforced, and was not given a mandate to intervene",x:["It arrived after the genocide ended","It sided with the militias","It had no commander"]},
{u:3,l:6,t:"Theories & Concepts",d:2,q:"Which UN doctrine was shaped by the failure to intervene in Rwanda?",a:"The 'Responsibility to Protect'",x:["Complementarity","Collective security","Cultural relativism"]},
{u:3,l:6,t:"Cases & Rulings",d:2,q:"What charges led to Mandela's life sentence?",a:"Sabotage, after his 1962 arrest",x:["Treason and murder","Tax evasion","Illegal emigration"]},
{u:3,l:6,t:"Cases & Rulings",d:2,q:"What forces combined to end apartheid?",a:"International pressure including sanctions and a global anti-apartheid movement, plus internal resistance",x:["A UN military invasion","A ruling by the ICC","A decision by the British Parliament"]},
{u:3,l:6,t:"Theories & Concepts",d:2,q:"What did Mandela's presidency emphasize over retribution?",a:"Reconciliation",x:["Prosecution","Deportation","Segregation"]},
{u:3,l:6,t:"Theories & Concepts",d:2,q:"Why was the Truth and Reconciliation Commission controversial?",a:"Some victims felt it prioritized national unity over individual justice, since perpetrators who told the truth could get amnesty",x:["It executed too many people","It refused to hear any testimony","It was run by the apartheid government"]},
{u:3,l:6,t:"Cases & Rulings",d:2,q:"Where did Paul Rusesabagina shelter over a thousand refugees?",a:"The Hôtel des Mille Collines in Kigali",x:["Robben Island","A UN compound in Nairobi","The Belgian embassy"]},
{u:3,l:6,t:"Cases & Rulings",d:2,q:"In what year was Mandela released from prison?",a:"1990",x:["1994","1962","1985"]},
{u:3,l:6,t:"Theories & Concepts",d:2,q:"What apartheid restrictions did the course name?",a:"Classifying people by race and restricting where Black South Africans could live, work, and move",x:["Banning all religions","Requiring military service","Abolishing all courts"]},
{u:3,l:6,t:"Cases & Rulings",d:3,q:"A country offers amnesty to perpetrators who publicly confess, in order to heal national divisions. Which historical model is this?",a:"South Africa's Truth and Reconciliation Commission",x:["The Nuremberg Trials","The ICC","The Rwandan genocide tribunal"]},
{u:3,l:6,t:"Theories & Concepts",d:3,q:"Which Unit 1 principle of justice is most directly at stake when perpetrators receive amnesty instead of prosecution?",a:"Equality — the same law applied to everyone",x:["Impartiality","Habeas corpus","Innocence until proven guilty"]},
{u:3,l:6,t:"Theories & Concepts",d:3,q:"A state says the outside world has no right to interfere with how it treats its own people. Which concept is it invoking?",a:"Sovereignty",x:["Responsibility to Protect","Complementarity","Universalism"]},
{u:3,l:6,t:"Laws & Documents",d:3,q:"Mass killings are underway and early warnings are clear, but the international community does not act. Which case is this most like?",a:"Rwanda, 1994",x:["South Africa, 1994","Nuremberg, 1945","Guantánamo, 2002"]},
{u:3,l:6,t:"Cases & Rulings",d:3,q:"A leader chooses national unity over prosecuting former oppressors. Which figure does this echo?",a:"Nelson Mandela",x:["Paul Rusesabagina","Roméo Dallaire","F.W. de Klerk"]},
{u:3,l:6,t:"Laws & Documents",d:3,q:"Which UDHR principle did the Rwandan genocide most clearly violate?",a:"That human rights are a matter of legitimate international concern, not just domestic policy",x:["The right to an interpreter","Freedom of the press","Mobility rights"]},
{u:3,l:6,t:"Cases & Rulings",d:3,q:"Economic sanctions and a global movement pressure a government to change a discriminatory legal system. Which case is this?",a:"Apartheid South Africa",x:["Rwanda","Nazi Germany","Guantánamo Bay"]},
{u:3,l:6,t:"Theories & Concepts",d:4,q:"Is it ever appropriate to trade full legal justice for national reconciliation? What would need to be true?",a:"Possibly, if the alternative is continued conflict and the truth is fully disclosed — but it costs victims individual justice",x:["Never — reconciliation is always wrong","Always — justice is unimportant","Only if perpetrators are executed first"]},
{u:3,l:6,t:"Cases & Rulings",d:4,q:"How should the conflict between sovereignty and the responsibility to prevent atrocities be resolved, according to the lesson's framing?",a:"Rwanda suggests sovereignty cannot be absolute when mass atrocities occur — hence the 'Responsibility to Protect'",x:["Sovereignty always wins","The UN should govern all states","There is no conflict"]},
{u:3,l:6,t:"Laws & Documents",d:4,q:"Why did the international community fail to intervene in Rwanda despite the UDHR's principles?",a:"The UDHR declared rights an international concern but provided no enforcement; states lacked the will to reinforce the UN mission",x:["The UDHR excluded Africa","The genocide was kept secret","The UN did not exist yet"]},
{u:3,l:6,t:"Laws & Documents",d:4,q:"Compare how South Africa and Rwanda illustrate the role of the international community.",a:"In South Africa, international pressure helped end apartheid; in Rwanda, the international community largely failed to act",x:["Both show successful UN military intervention","Both show the ICC prosecuting leaders","Neither involved international actors"]},
{u:3,l:6,t:"Cases & Rulings",d:4,q:"How does Mandela's TRC relate to Unit 1's consequential vs. categorical reasoning?",a:"Amnesty for truth is a consequential choice (national healing) over a categorical demand that crimes always be punished",x:["It is purely categorical","It shows reasoning is irrelevant to law","It applies only to legal positivism"]},
{u:3,l:6,t:"Cases & Rulings",d:4,q:"Why does the course call Rwanda 'one of the central case studies in international law'?",a:"It shapes the debate over when and how the international community should intervene to stop mass atrocities",x:["Because the ICC was founded there","Because it was the first genocide","Because the UN won the conflict"]},

/* ---------- Lesson 7: Malala & the Hidden Labour Behind AI ---------- */
{u:3,l:7,t:"People & Institutions",d:1,q:"Where is Malala Yousafzai from?",a:"The Swat Valley, Pakistan",x:["Kabul, Afghanistan","Nairobi, Kenya","Kigali, Rwanda"]},
{u:3,l:7,t:"People & Institutions",d:1,q:"Who shot Malala in 2012?",a:"A Taliban gunman",x:["A police officer","A rival student","A soldier"]},
{u:3,l:7,t:"People & Institutions",d:1,q:"How old was Malala when she became the youngest-ever Nobel Peace Prize laureate?",a:"17",x:["15","21","12"]},
{u:3,l:7,t:"People & Institutions",d:1,q:"With whom did Malala share the 2014 Nobel Peace Prize?",a:"Kailash Satyarthi",x:["Nelson Mandela","Desmond Tutu","Eleanor Roosevelt"]},
{u:3,l:7,t:"Laws & Documents",d:1,q:"Which UDHR article protects the right to education?",a:"Article 26",x:["Article 19","Article 23","Article 5"]},
{u:3,l:7,t:"Laws & Documents",d:1,q:"Which UDHR article protects freedom of expression?",a:"Article 19",x:["Article 26","Article 3","Article 9"]},
{u:3,l:7,t:"Laws & Documents",d:1,q:"Which UDHR article covers just and favourable conditions of work and fair pay?",a:"Article 23",x:["Article 25","Article 10","Article 26"]},
{u:3,l:7,t:"Laws & Documents",d:1,q:"Which UDHR article prohibits cruel, inhuman, or degrading treatment?",a:"Article 5",x:["Article 9","Article 23","Article 1"]},
{u:3,l:7,t:"People & Institutions",d:1,q:"Which Kenya-based outsourcing firm did OpenAI contract for content labelling?",a:"Sama",x:["Amazon","Safaricom","Meta"]},
{u:3,l:7,t:"People & Institutions",d:1,q:"What organization did Malala found to continue her advocacy?",a:"The Malala Fund",x:["The Innocence Project","Centurion Ministries","Human Rights Watch"]},
{u:3,l:7,t:"People & Institutions",d:1,q:"On what date was Malala shot?",a:"October 9, 2012",x:["December 10, 1948","April 6, 1994","August 19, 2011"]},
{u:3,l:7,t:"People & Institutions",d:2,q:"Why did Malala begin advocating for girls' education?",a:"The Taliban banned girls from attending school in the Swat Valley",x:["Her school was closed for lack of funding","She was denied a scholarship","A UN report asked her to"]},
{u:3,l:7,t:"People & Institutions",d:2,q:"Why was Malala shot?",a:"In direct retaliation for her activism",x:["By accident during a protest","Because she refused to pay a bribe","Because of a family dispute"]},
{u:3,l:7,t:"Cases & Rulings",d:2,q:"What did Sama workers have to do for OpenAI?",a:"Read and label tens of thousands of text passages describing graphic violence, hate speech, and sexual abuse",x:["Write ChatGPT's code","Translate the UDHR","Build computer servers"]},
{u:3,l:7,t:"Cases & Rulings",d:2,q:"Why was the labelling work necessary?",a:"To train ChatGPT's safety systems to detect and filter out toxic content from scraped internet data",x:["To improve the chatbot's grammar","To translate it into Swahili","To advertise the product"]},
{u:3,l:7,t:"Cases & Rulings",d:2,q:"What was the wage gap in the Sama case?",a:"Workers took home roughly $1.32–$2 per hour while OpenAI paid Sama about $12.50 per hour",x:["Workers earned $12.50 and OpenAI paid $20","Workers were unpaid volunteers","Workers earned the same as OpenAI engineers"]},
{u:3,l:7,t:"Cases & Rulings",d:2,q:"What effects did Sama workers describe?",a:"Lasting psychological effects, including recurring disturbing thoughts, with limited mental health support",x:["Physical injuries from machinery","Improved mental health","No effects at all"]},
{u:3,l:7,t:"Cases & Rulings",d:2,q:"Why did Sama end its content contracts with OpenAI early?",a:"Internal concerns about the work's psychological toll and public scrutiny of similar outsourced moderation work",x:["OpenAI stopped paying","The Kenyan government banned it","The work was completed"]},
{u:3,l:7,t:"Theories & Concepts",d:2,q:"What theme from Lesson 1 does Malala's continued advocacy illustrate?",a:"A right declared in principle (education for all) still needs sustained work to become a right realized in practice",x:["Rights are divisible","Rights come only from governments","Education is not a human right"]},
{u:3,l:7,t:"Theories & Concepts",d:2,q:"What does the AI labelling case reveal about 'invisible' rights issues?",a:"Some of the most significant contemporary cases involve hidden labour deep in global supply chains",x:["All rights abuses involve visible violence","Technology companies have no supply chains","Rights issues are always reported quickly"]},
{u:3,l:7,t:"Theories & Concepts",d:2,q:"How does the Sama case connect to Unit 2's content?",a:"It ties to labour law — workers in the Global South doing difficult work for Global North companies without matching protections",x:["It is a court hierarchy question","It concerns the notwithstanding clause","It is about racial profiling"]},
{u:3,l:7,t:"Theories & Concepts",d:2,q:"What is the key difference in 'visibility' between Malala's case and the AI labour case?",a:"Malala's became globally visible almost immediately; the AI case took a dedicated investigative report to surface",x:["Both were hidden for decades","Both were immediately famous","The AI case was more famous than Malala's"]},
{u:3,l:7,t:"Modern Connections",d:3,q:"A journalist is attacked for publishing criticism of a government. Which UDHR article is most directly engaged?",a:"Article 19 — freedom of expression",x:["Article 26 — education","Article 23 — work","Article 25 — standard of living"]},
{u:3,l:7,t:"Modern Connections",d:3,q:"A region bars girls from school. Which UDHR article is violated?",a:"Article 26",x:["Article 19","Article 5","Article 9"]},
{u:3,l:7,t:"Modern Connections",d:3,q:"Workers are exposed to traumatic material for very low pay with little support. Which two UDHR articles are engaged?",a:"Article 23 (conditions of work) and Article 5 (degrading treatment)",x:["Article 26 and Article 19","Article 3 and Article 9","Article 10 and Article 25"]},
{u:3,l:7,t:"People & Institutions",d:3,q:"A company pays its contractor far more than the contractor pays its workers. Who bears responsibility, according to the discussion question?",a:"Arguably both the company and the contractor — the lesson asks students to reason about shared responsibility",x:["Only the workers","Neither — wages are private","Only the government of Kenya"]},
{u:3,l:7,t:"Theories & Concepts",d:3,q:"A contractor argues it pays above the local minimum wage, so there is no ethical problem. Which Lesson 7 question challenges this?",a:"Whether paying above minimum wage settles the ethical question, or whether the psychological toll and wage gap also matter",x:["Whether the minimum wage is too high","Whether the workers were volunteers","Whether the company is Canadian"]},
{u:3,l:7,t:"Cases & Rulings",d:3,q:"A human rights defender is targeted specifically because they speak out. Which case illustrates this risk?",a:"Malala Yousafzai",x:["The Sama workers","Desmond Cole","David Milgaard"]},
{u:3,l:7,t:"Modern Connections",d:3,q:"A student uses an AI chatbot and never thinks about who filtered its training data. Which concept does Lesson 7 raise?",a:"Hidden labour in global supply chains",x:["Cultural relativism","Judicial review","Carding"]},
{u:3,l:7,t:"Theories & Concepts",d:4,q:"Why might some human rights issues become globally visible instantly while others stay hidden for years?",a:"Dramatic, personal, visible violence draws media attention; invisible labour buried in supply chains needs investigative reporting to surface",x:["Hidden issues are less serious","Media always covers labour issues first","Visibility depends only on the victim's age"]},
{u:3,l:7,t:"Modern Connections",d:4,q:"How do Malala's case and the Sama case together illustrate the two categories of rights from Lesson 1?",a:"Malala's case engages civil and political rights (expression) and education; Sama engages economic and social rights (work conditions)",x:["Both concern only civil rights","Both concern only economic rights","Neither fits the categories"]},
{u:3,l:7,t:"Modern Connections",d:4,q:"Does paying above a country's minimum wage settle the ethical question in the Sama case? What else is at stake?",a:"Not necessarily — the psychological harm, the size of the gap between what OpenAI paid and workers received, and lack of support also matter",x:["Yes — legal minimums settle all ethical questions","No — because minimum wages are illegal","Yes — because the workers consented"]},
{u:3,l:7,t:"Modern Connections",d:4,q:"How does the Sama case connect Unit 2's labour law to international human rights?",a:"Domestic labour law may not protect workers in a global supply chain, so international standards like UDHR Article 23 become the relevant framework",x:["Labour law has no connection to human rights","The UDHR replaces all labour law","Kenyan law applies to OpenAI directly"]},
{u:3,l:7,t:"Modern Connections",d:4,q:"What do Malala's and the Sama workers' stories have in common despite their differences?",a:"Both show rights declared in principle (education, fair work) that require effort and visibility to be realized in practice",x:["Both involved the ICC","Both took place in Pakistan","Both were resolved by courts"]},

/* ---------- Lesson 8: ICE & Guantánamo Bay ---------- */
{u:3,l:8,t:"People & Institutions",d:1,q:"What does ICE stand for?",a:"Immigration and Customs Enforcement",x:["International Court of Equity","Internal Civil Enforcement","Immigration Court of Europe"]},
{u:3,l:8,t:"People & Institutions",d:1,q:"Where is the U.S. military prison at Guantánamo Bay located?",a:"Cuba",x:["Puerto Rico","Florida","El Salvador"]},
{u:3,l:8,t:"People & Institutions",d:1,q:"Who is the subject of The Mauritanian?",a:"Mohamedou Ould Slahi",x:["Paul Rusesabagina","Donald Rumsfeld","Jon Ossoff"]},
{u:3,l:8,t:"Modern Connections",d:1,q:"What is the title of Slahi's memoir?",a:"Guantánamo Diary",x:["The Skin We're In","Invictus","Hotel Rwanda"]},
{u:3,l:8,t:"Laws & Documents",d:1,q:"Which UDHR article protects against arbitrary arrest or detention?",a:"Article 9",x:["Article 5","Article 10","Article 25"]},
{u:3,l:8,t:"Laws & Documents",d:1,q:"Which UDHR article guarantees a fair and public hearing?",a:"Article 10",x:["Article 9","Article 3","Article 23"]},
{u:3,l:8,t:"Laws & Documents",d:1,q:"Which UDHR article covers life, liberty, and security of person?",a:"Article 3",x:["Article 5","Article 1","Article 25"]},
{u:3,l:8,t:"Laws & Documents",d:1,q:"Which UDHR article covers an adequate standard of living, including medical care?",a:"Article 25",x:["Article 23","Article 26","Article 3"]},
{u:3,l:8,t:"People & Institutions",d:1,q:"Which U.S. Secretary of Defense personally approved Slahi's torture as a 'Special Project'?",a:"Donald Rumsfeld",x:["James Boasberg","Jon Ossoff","Randolph Moss"]},
{u:3,l:8,t:"People & Institutions",d:1,q:"Which senator released a January 2026 investigation into immigration detention abuses?",a:"Jon Ossoff",x:["Donald Rumsfeld","James Boasberg","Randolph Moss"]},
{u:3,l:8,t:"People & Institutions",d:1,q:"In what year did Guantánamo Bay prison open?",a:"2002",x:["2001","1994","2016"]},
{u:3,l:8,t:"Cases & Rulings",d:1,q:"How many years was Slahi held without charge?",a:"14",x:["7","23","2"]},
{u:3,l:8,t:"Cases & Rulings",d:2,q:"What did Human Rights Watch report about deaths in ICE custody?",a:"52 deaths in the first 500 days of the current administration — a 140% increase in the mortality rate",x:["No deaths at all","5 deaths over ten years","A 14% decrease in deaths"]},
{u:3,l:8,t:"Cases & Rulings",d:2,q:"What happened to the DHS Office for Civil Rights and Civil Liberties in 2025?",a:"It was cut from roughly 150 staff to a small remaining group, reducing independent monitoring",x:["It was expanded to 1,500 staff","It was moved to Guantánamo","It was given power to prosecute"]},
{u:3,l:8,t:"Cases & Rulings",d:2,q:"What allegations did the 2025 Human Rights Watch investigation document at Florida detention centres?",a:"Denial of medical care, overcrowding, and people shackled for extended periods",x:["Excessive luxury","Early release of all detainees","Free legal counsel for all"]},
{u:3,l:8,t:"Cases & Rulings",d:2,q:"What did the Ossoff investigation identify?",a:"Over 1,000 credible reports of abuses since January 2025, including mistreatment of pregnant women and children",x:["No abuses of any kind","Ten minor complaints","Abuses only in Canada"]},
{u:3,l:8,t:"Cases & Rulings",d:2,q:"Of roughly 780 men held at Guantánamo, how many were convicted of a crime?",a:"Only a small number",x:["All of them","About half","Exactly 780"]},
{u:3,l:8,t:"Cases & Rulings",d:2,q:"How did Slahi end up at Guantánamo?",a:"Detained by Mauritanian authorities at U.S. request in 2001, transferred through Jordan and Afghanistan, and sent to Guantánamo in 2002",x:["He surrendered voluntarily","He was arrested in Florida","He was convicted in Mauritania"]},
{u:3,l:8,t:"Cases & Rulings",d:2,q:"What forms of torture was Slahi subjected to?",a:"Prolonged isolation, sleep deprivation, and threats against him and his mother",x:["Forced labour in a factory","Public trial by jury","Deportation to Canada"]},
{u:3,l:8,t:"Cases & Rulings",d:2,q:"What happened after a federal judge ruled Slahi's detention unlawful in 2010?",a:"The government appealed and he remained held for six more years",x:["He was released the next day","He was convicted and executed","He was transferred to Canada"]},
{u:3,l:8,t:"Cases & Rulings",d:2,q:"When was Slahi released?",a:"October 2016, returned to Mauritania",x:["January 2002","December 2010","February 2025"]},
{u:3,l:8,t:"Modern Connections",d:2,q:"What change at Guantánamo since February 2025 connects it to Unit 2?",a:"The U.S. began transferring immigration detainees there, linking to the Alien Enemies Act deportations",x:["It was closed permanently","It was handed to Cuba","It became a UN facility"]},
{u:3,l:8,t:"Theories & Concepts",d:2,q:"What recurring theme appears across the ICE reports?",a:"Reduction of independent oversight alongside reports of harm",x:["Increased transparency","More funding for inspectors","Faster hearings"]},
{u:3,l:8,t:"Laws & Documents",d:2,q:"If the ICE detention conditions occurred in a Canadian facility, which Charter sections would likely be engaged?",a:"Section 7 (fundamental justice) and section 12 (cruel and unusual punishment)",x:["Sections 3 and 4","Sections 16 and 23","Section 33 only"]},
{u:3,l:8,t:"Theories & Concepts",d:2,q:"What pattern connects Unit 2's comparative justice lesson with Unit 3's Lesson 8?",a:"Due process denied, oversight reduced, and international human rights standards invoked as the evaluation framework",x:["Courts always protecting detainees","Rights being expanded","Oversight being strengthened"]},
{u:3,l:8,t:"Modern Connections",d:3,q:"A person is detained for years without ever being charged. Which UDHR article is most directly violated?",a:"Article 9 — freedom from arbitrary detention",x:["Article 26 — education","Article 23 — work","Article 19 — expression"]},
{u:3,l:8,t:"Modern Connections",d:3,q:"A detainee is denied any hearing to contest their detention. Which UDHR article is violated?",a:"Article 10 — fair and public hearing",x:["Article 25","Article 3","Article 26"]},
{u:3,l:8,t:"Modern Connections",d:3,q:"Detainees are denied adequate food, water, and medical care. Which UDHR article is most directly engaged?",a:"Article 25 — adequate standard of living including medical care",x:["Article 19","Article 10","Article 9"]},
{u:3,l:8,t:"Theories & Concepts",d:3,q:"A government cuts the staff of its own oversight body while abuse reports rise. Why does this matter?",a:"Reduced oversight makes it harder to know the true scale of a problem, even if conditions haven't changed",x:["It proves conditions have improved","It has no effect on reporting","It automatically ends the abuse"]},
{u:3,l:8,t:"People & Institutions",d:3,q:"Which Canadian institutions from Units 1 and 2 play an oversight role similar to what the DHS office was meant to do?",a:"Courts, tribunals, and the SIU",x:["The Senate and the Governor General","The Famous Five","The CRA"]},
{u:3,l:8,t:"Modern Connections",d:3,q:"Write a one-sentence legal argument linking Slahi's case to both a UDHR article and a Charter section. Which pairing is correct?",a:"UDHR Article 9 (arbitrary detention) and Charter section 9 (arbitrary detention)",x:["UDHR Article 26 and Charter section 23","UDHR Article 19 and Charter section 6","UDHR Article 23 and Charter section 3"]},
{u:3,l:8,t:"Modern Connections",d:3,q:"Someone is tortured during detention. Which UDHR article and Charter section are the closest pair?",a:"UDHR Article 5 and Charter section 12",x:["UDHR Article 10 and Charter section 3","UDHR Article 25 and Charter section 6","UDHR Article 3 and Charter section 33"]},
{u:3,l:8,t:"Cases & Rulings",d:3,q:"A court rules a detention unlawful, but the person stays detained for years during appeals. Which case does this describe?",a:"Mohamedou Ould Slahi",x:["David Milgaard","Dee Brown","Nelson Mandela"]},
{u:3,l:8,t:"Modern Connections",d:4,q:"Why does Slahi's case illustrate three UDHR articles being violated at once?",a:"He was detained without charge (Art. 9), tortured (Art. 5), and never given a fair hearing (Art. 10)",x:["He was denied education, work, and expression","He was denied voting, mobility, and language rights","Only one article applied to his case"]},
{u:3,l:8,t:"Theories & Concepts",d:4,q:"Why might detention conditions receive less public attention than a single dramatic event?",a:"Ongoing, hidden conditions lack a single visible moment, and reduced oversight limits the information available",x:["Because detention is always lawful","Because detainees have no rights","Because the media is not allowed to report"]},
{u:3,l:8,t:"Laws & Documents",d:4,q:"Is it useful for Canadian students to study another country's human rights record in depth? What is the course's reasoning?",a:"It lets students apply Charter and UDHR frameworks to real cases and reflect on what the same conditions would mean in Canada",x:["No — only Canadian cases matter","It is required by the U.S. government","It replaces studying Canadian law"]},
{u:3,l:8,t:"Theories & Concepts",d:4,q:"How does Lesson 8 synthesize Unit 2's Lesson 6 and Unit 3?",a:"Both examine the same pattern: due process denied, oversight reduced, and international standards used as the framework for evaluation",x:["Both conclude U.S. law is superior","Both focus on the Senate","Both concern only Canadian cases"]},
{u:3,l:8,t:"Modern Connections",d:4,q:"How does the transfer of immigration detainees to Guantánamo link Unit 2 and Unit 3?",a:"It connects the Alien Enemies Act deportations (Unit 2) to a facility defined by indefinite detention without charge (Unit 3)",x:["It shows Guantánamo has closed","It concerns Canadian immigration","It involves the notwithstanding clause"]},
{u:3,l:8,t:"Laws & Documents",d:4,q:"What does the course mean by invoking 'international human rights standards as the framework'?",a:"Using the UDHR and related treaties as the measure for evaluating what happened, rather than only domestic law",x:["Letting the UN run domestic courts","Replacing the Charter with the UDHR","Ignoring international law"]}
);
